package com.mohymods.kingdomsmp.gametest;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.LevelResource;
/** Full approved quantities from future native OreFeature writes; no quest/ore/count/rank injection. */
final class NativeJourneyOreRuntime {
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(project.owner());h.assertTrue(p!=null,"Original paid Miner owner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var data=NativeOreSavedData.get(server);var old=store.professions(p.getUUID()).track(Profession.MINER);var marker=server.getWorldPath(LevelResource.ROOT).resolve("native-journey-ore-proof.nbt");
  if(java.nio.file.Files.exists(marker)){
   h.assertTrue(old.xp()==1600&&old.completedQuestIds().size()==12&&store.professions(p.getUUID()).rank(Profession.MINER,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"Actual12earned mining objectives/1600XP restored");var proof=AtomicNbt.read(marker);var retained=BlockPos.of(proof.getLong("retained"));level.getChunkAt(retained);h.assertTrue(level.getChunkAt(retained).getData(NativeOreProvenance.MARKS).at(retained.asLong())!=null,"Untouched genuine rare seam attachment persists");
   for(var id:NativeOreQuests.GOALS.keySet())if(id.contains("/j")&&!id.equals(NativeGeology.QUEST))h.assertTrue(NativeOreQuests.count(p,id)==NativeOreQuests.GOALS.get(id),"Exact legitimate new band count persists");h.assertTrue(!data.evidence().record(UUID.randomUUID(),ProfessionRank.JOURNEYMAN,"diamond","minecraft:overworld",proof.getLong("spent")),"Saved global spent rare position cannot be awarded to another player");h.assertTrue(MineAccessSavedData.get(server).evidence().route(p.getUUID())!=null&&ConstructionService.structureIntact(level,project),"Original actual retained descent and Mine-Doran preserved");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("NATIVE_JOURNEY_ORE_RESTART_PASSED: exact104native Journeyman ores/12earned1600XP/old8Apprentice/rare attachment/global spent/actual descent/Mine-Doran/native receipt restored");return;
  }
  h.assertTrue(old.xp()==800&&old.completedQuestIds().size()==8&&store.professions(p.getUUID()).rank(Profession.MINER,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"Begins from genuinely earned full native Apprentice only");
  Map<String,List<BlockPos>> seams=new HashMap<>();for(String m:List.of("redstone","lapis","gold","diamond"))seams.put(m,new ArrayList<>());
  for(int x=176;x<180;x++)for(int z=144;z<148;z++)for(var at:NativeCopperRuntime.generated(h,p,x,z)) {var m=NativeCopperRuntime.metric(p,at);if(seams.containsKey(m)&&!seams.get(m).contains(at))seams.get(m).add(at);}
  for(var entry:seams.entrySet())h.assertTrue(entry.getValue().size()>=NativeOreQuests.GOALS.get(quest(entry.getKey()))+5,"Actual native new seam quantity "+entry.getKey()+"="+entry.getValue().size());
  DimensionTravelRuntimeTests.seed(server,3);var low=seams.get("redstone").remove(0);NativeCopperRuntime.mine(h,p,low);h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.JOURNEYMAN,"redstone")==0,"Native Tier3ore removal remains usable without locked Tier4credit");DimensionTravelRuntimeTests.seed(server,4);
  var replaced=seams.get("diamond").remove(0);level.setBlock(replaced,Blocks.AIR.defaultBlockState(),3);level.setBlock(replaced,Blocks.DIAMOND_ORE.defaultBlockState(),3);NativeCopperRuntime.mine(h,p,replaced);h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.JOURNEYMAN,"diamond")==0,"Replaced real rare ore cannot retain source proof");
  var denied=seams.get("gold").get(0);var guard=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("JourneyOreClaimGuard".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"JourneyGuard");ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(guard,denied);BlacksmithRepairRuntime.near(p,denied);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));h.assertTrue(!p.gameMode.destroyBlock(denied)&&NativeOreProvenance.capture(p,denied,true)==null,"Independent current claim refuses actual native rare mining");ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(p,denied);
  long spent=0;for(var metric:List.of("redstone","lapis","gold","diamond")){int goal=NativeOreQuests.GOALS.get(quest(metric));for(var at:seams.get(metric).subList(0,goal)){NativeCopperRuntime.mine(h,p,at);spent=at.asLong();}h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.JOURNEYMAN,metric)==goal,"Full actual native successful ore removals: "+metric);}
  CreateCraftRuntime.counter(p,project);for(var metric:List.of("redstone","lapis","gold","diamond")){var review=ProfessionService.review(p,"quest:"+quest(metric));ProfessionService.confirm(p,review.nonce());boolean refused=false;try{ProfessionService.review(p,"quest:"+quest(metric));}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Native rare ore award cannot repeat");}
  var after=store.professions(p.getUUID()).track(Profession.MINER);h.assertTrue(after.xp()==1600&&after.completedQuestIds().size()==12&&store.professions(p.getUUID()).rank(Profession.MINER,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"Four genuine full quantities earn800XP preserving all8original proofs");h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(store.professions(p.getUUID())),"New native receipts and old roster reopen atomically");CommerceService.verifyReceipt(p);var proof=new CompoundTag();proof.putLong("spent",spent);proof.putLong("retained",seams.get("diamond").get(9).asLong());AtomicNbt.write(marker,proof);com.mojang.logging.LogUtils.getLogger().info("NATIVE_JOURNEY_ORE_NATIVE_PASSED: real future asynchronous OreFeature ProtoChunk rare seams, actual48redstone24lapis24Overworldgold8diamond/native correct-tool removal, Tier3/replacement/currentclaim/replay refusals, all8oldproofs+4real new1600XP/original Doran/native receipt; private future terrain/tools/tier boundaries only, no ore/count/quest/XP/rank injection");
 }
 static String quest(String metric){return "kingdom_smp:miner/"+switch(metric){case "redstone"->"j01";case "lapis"->"j02";case "gold"->"j03";case "diamond"->"j04";default->throw new IllegalArgumentException(metric);};}
}
